// Generated by Kapex Cortex (`cortex init`) from templates/opencode-plugin.ts. Machine-specific: gitignored.
// OpenCode 2.x plugin format: default export { id, setup(ctx) } (verified against OpenCode 2.2.5's loader).
import { spawn } from "node:child_process";
import { appendFileSync, readFileSync, realpathSync, statSync } from "node:fs";
import { isAbsolute, join, relative } from "node:path";

const NODE = "__NODE__";
const CLI = "__CLI__";

function run(event: string, payload: Record<string, unknown>): Promise<string> {
  return new Promise((resolve) => {
    const child = spawn(NODE, [...(CLI ? [CLI] : []), "hook", "opencode." + event], { stdio: ["pipe", "pipe", "ignore"] });
    let out = "";
    child.stdout.on("data", (d: Buffer) => (out += d));
    child.on("close", () => resolve(out));
    child.on("error", () => resolve(""));
    child.stdin.end(JSON.stringify(payload));
  });
}

type Deny = { kind: "bash" | "path"; pattern: string; rule: string };
let cache: { mtime: number; denies: Deny[]; readGuard: boolean } = { mtime: -1, denies: [], readGuard: false };
function load(directory: string) {
  const f = join(directory, ".vault", "enforce.json");
  try {
    const m = statSync(f).mtimeMs;
    if (m !== cache.mtime) { const j = JSON.parse(readFileSync(f, "utf8")); cache = { mtime: m, denies: j.denies ?? [], readGuard: j.readGuard === true }; }
  } catch {
    cache = { mtime: -1, denies: [], readGuard: false };
  }
  return cache;
}
const denies = (directory: string): Deny[] => load(directory).denies;

// Read guard (opt-in: kc prefs set readGuard on), same as the Claude Code panel's: the first whole read of a
// text file over 40 KB is refused once with a hint to read a part; reading it again goes through.
const GUARD_BYTES = 40_000;
const warned = new Set<string>();
function readGuardHit(tool: string, input: any, file: string | undefined, directory: string): string | null {
  if (!file || !/^read$/i.test(tool) || !load(directory).readGuard) return null;
  const has = (o: any, k: string): boolean => !!o && typeof o === "object" && (o[k] !== undefined || Object.values(o).some((v) => has(v, k)));
  if (has(input, "offset") || has(input, "limit") || /\.(?:png|jpe?g|gif|webp|bmp|ico|svg|pdf|ipynb)$/i.test(file)) return null;
  const abs = isAbsolute(file) ? file : join(directory, file);
  let size = 0;
  try { const st = statSync(abs); if (!st.isFile()) return null; size = st.size; } catch { return null; }
  if (size < GUARD_BYTES || warned.has(abs)) return null;
  warned.add(abs);
  return `Kapex Cortex read guard: ${abs.split(/[\\/]/).pop()} is ${Math.round(size / 1000)} KB, about ${Math.round(size / 4000)}k tokens. Read only the part you need (offset and limit), or search it with grep first. If you really need all of it, read it again and it will load.`;
}

// Same matching rules as src/core/enforce.ts (bashDenied / pathDenied), which are unit-tested.
function bashHit(command: string, list: Deny[]): Deny | undefined {
  const raw = command.split(/&&|\|\||;|\||\n|\$\(|`/).map((s) => s.trim()).filter(Boolean);
  const segs = raw.flatMap((s) => [s, s.replace(/^(?:sudo\s+|env\s+\S+=\S+\s+|command\s+|exec\s+)+/, "")]);
  return list.find((d) => d.kind === "bash" && segs.some((s) => s === d.pattern || s.startsWith(d.pattern + " ")));
}
function globRe(g: string): RegExp {
  const re = g.replace(/[.+^${}()|[\]\\]/g, "\\$&").replace(/\*\*/g, "\u0000").replace(/\*/g, "[^/]*").replace(/\u0000/g, ".*");
  return new RegExp("^" + re + "$");
}
function pathHit(file: string, directory: string, list: Deny[]): Deny | undefined {
  // globs use "/"; on Windows relative() returns "config\\prod\\a.yaml"
  const rel = (isAbsolute(file) ? relative(directory, file) : file).replace(/\\/g, "/").replace(/^\.\//, "");
  return list.find((d) => d.kind === "path" && globRe(d.pattern).test(rel));
}

/** Find the first string field that looks like a shell command / file path, whatever the tool's arg names are. */
function pick(obj: any, keys: string[]): string | undefined {
  if (!obj || typeof obj !== "object") return undefined;
  for (const k of keys) if (typeof obj[k] === "string") return obj[k];
  for (const v of Object.values(obj)) {
    if (v && typeof v === "object") {
      const hit = pick(v, keys);
      if (hit) return hit;
    }
  }
  return undefined;
}

export default {
  id: "kapex-cortex",
  setup: (ctx: any) => {
    const directory: string = ctx?.location?.directory ?? process.cwd();
    const debugLog = join(directory, ".vault", "private", "opencode-plugin.log");
    const debug = (msg: string) => {
      try { appendFileSync(debugLog, new Date().toISOString() + " " + msg + "\n"); } catch { /* ignore */ }
    };
    const putEntries = async (sessionID: string, json: string) => {
      try {
        const entries = (JSON.parse(json).entries ?? {}) as Record<string, string>;
        for (const [key, value] of Object.entries(entries)) {
          if (value === "") await ctx.session.instructions.entry.remove({ sessionID, key }).catch(() => {});
          else await ctx.session.instructions.entry.put({ sessionID, key, value });
        }
        if (Object.keys(entries).length) debug(`entries put: ${Object.keys(entries).join(",")} session=${sessionID}`);
      } catch (e) {
        debug(`entry put failed: ${(e as Error)?.message ?? e}`);
      }
    };

    // OpenCode runs ONE server for all projects and the event stream is server-wide: only act on sessions
    // that belong to this plugin's own directory (otherwise one project's plugin captures another's chats).
    const real = (d: string) => { try { return realpathSync(d); } catch { return d; } };
    const home = real(directory);
    const owned = new Map<string, boolean>();
    const ownsSession = async (ev: any, sessionID: string): Promise<boolean> => {
      if (owned.has(sessionID)) return owned.get(sessionID)!;
      let dir: string | undefined = ev?.data?.location?.directory ?? ev?.location?.directory;
      if (!dir) {
        try {
          const s = await ctx.session.get({ sessionID });
          dir = s?.location?.directory ?? s?.directory ?? s?.data?.location?.directory ?? s?.data?.directory;
        } catch { /* unknown: treat as not ours */ }
      }
      if (!dir) return true; // unknown: Cortex's own database check (sessionBelongs) decides, nothing cached
      const mine = real(dir) === home;
      owned.set(sessionID, mine);
      return mine;
    };

    const ac = new AbortController();
    (async () => {
      const stream = ctx.event.subscribe({
        // OpenCode 2 ends a turn with session.execution.{succeeded,failed,interrupted} (verified on 2.2.5);
        // "session.idle" is the 1.x name and is kept for older servers.
        types: ["session.created", "session.execution.succeeded", "session.execution.failed", "session.execution.interrupted", "session.idle", "session.compaction.ended"],
        signal: ac.signal,
      });
      for await (const ev of stream) {
        const type: string = ev?.type ?? "";
        const sessionID: string = ev?.data?.sessionID ?? ev?.data?.id ?? ev?.properties?.sessionID ?? "";
        if (!sessionID) continue;
        if (!(await ownsSession(ev, sessionID))) continue;
        if (type === "session.created") await putEntries(sessionID, await run("created", { sessionID, directory }));
        else if (type.startsWith("session.execution.") || type === "session.idle") {
          await putEntries(sessionID, await run("idle", { sessionID, directory, outcome: type.split(".").pop() }));
        }
        else if (type === "session.compaction.ended") {
          await putEntries(sessionID, await run("compacted", { sessionID, directory, summary: ev?.data?.text ?? "" }));
        }
      }
    })().catch((e) => debug(`event loop ended: ${(e as Error)?.message ?? e}`));

    let hook: any;
    try {
      hook = ctx.tool.hook("execute.before", (input: any) => {
        const sid: string = input?.sessionID ?? input?.session?.id ?? "";
        if (sid && owned.get(sid) === false) return; // another project's session
        const tool: string = String(input?.tool ?? input?.name ?? input?.id ?? "");
        const file = pick(input, ["filePath", "file_path", "path", "file"]);
        const big = readGuardHit(tool, input, file, directory);
        if (big) { debug(`read guard: ${file}`); throw new Error(big); }
        const list = denies(directory);
        if (!list.length) return;
        const cmd = pick(input, ["command", "cmd"]);
        const hit = (cmd && /bash|shell|exec/i.test(tool + " " + Object.keys(input ?? {}).join(" ")) ? bashHit(cmd, list) : undefined)
          ?? (cmd ? bashHit(cmd, list) : undefined)
          ?? (file ? pathHit(file, directory, list) : undefined);
        if (hit) {
          debug(`blocked ${tool}: ${hit.kind} ${hit.pattern}`);
          throw new Error(`Blocked by a project rule (Kapex Cortex, .vault/INVARIANTS.md, ${hit.rule}): ${hit.kind === "bash" ? "command" : "path"} "${hit.pattern}" is not allowed.`);
        }
      });
    } catch (e) {
      debug(`tool hook unavailable: ${(e as Error)?.message ?? e}`);
    }
    debug(`loaded for ${directory}`);
    return () => {
      ac.abort();
      Promise.resolve(hook).then((h: any) => h?.dispose?.()).catch(() => {});
    };
  },
};
